findings.codeql_raw_query:
/**
 * @name HTML/JavaScript injection in markdown-it-py
 * @description Markdown parsers that allow HTML could lead to XSS if user input is not properly sanitized
 * @kind path-problem
 * @problem.severity error
 * @id py/html-injection-markdown-it
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module MarkdownItInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for markdown-it-py parsing operations
    exists(API::CallNode call |
      // markdown_it.MarkdownIt constructor or render method
      call = API::moduleImport("markdown_it").getMember("MarkdownIt").getACall() or
      call = API::moduleImport("markdown_it").getMember("render").getACall() or
      call = API::moduleImport("markdown_it").getMember("parse").getACall()
    |
      sink = call.getArg(0)  // The markdown text input argument
    )
  }
}

module MarkdownItInjectionFlow = TaintTracking::Global<MarkdownItInjectionConfig>;
import MarkdownItInjectionFlow::PathGraph

from MarkdownItInjectionFlow::PathNode source, MarkdownItInjectionFlow::PathNode sink
where MarkdownItInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "HTML/JavaScript injection in markdown-it-py from $@.", source.getNode(), "user input"
